parameters.jsCode:
// Zero-click pages - find the reason behind missing clicks
const cfg = $('Set Report Parameters').first().json;
const minImpressions = Number(cfg.minImpressions ?? 100);
const maxClicks = Number(cfg.maxClicks ?? 2);

const rows = $input.first().json.rows || [];
if (rows.length === 0) return [];

// operator queries are usually your own index checks, not real users
const OPERATOR = /^(site:|inurl:|cache:|related:|link:)/i;

// the same address with parameters (for example utm from a Google Business Profile link)
// is still the same page; no new URL() here, the Code node sandbox may not expose it
function normalizeUrl(u) {
  if (typeof u !== 'string') return u;
  return u.split('#')[0].split('?')[0];
}

const pages = new Map();
for (const r of rows) {
  const [rawPage, query] = r.keys;
  if (OPERATOR.test(query)) continue;

  const page = normalizeUrl(rawPage);
  const p = pages.get(page) || { page, clicks: 0, impressions: 0, positionSum: 0, n: 0, queries: [] };
  p.clicks += r.clicks;
  p.impressions += r.impressions;
  p.positionSum += r.position * r.impressions;
  p.n += r.impressions;
  p.queries.push({ query, impressions: r.impressions, clicks: r.clicks, position: r.position });
  pages.set(page, p);
}

const out = [];
for (const p of pages.values()) {
  if (p.impressions < minImpressions || p.clicks > maxClicks) continue;

  const position = p.n ? p.positionSum / p.n : 0;
  const ctr = p.impressions ? (p.clicks / p.impressions) * 100 : 0;

  let reason;
  if (position <= 5 && ctr < 0.3) reason = 'SERP_FEATURE';
  else if (position <= 10 && ctr < 1) reason = 'TITLE_META';
  else if (position <= 10) reason = 'INTENT_MISMATCH';
  else if (position <= 30) reason = 'POSITION_TOO_LOW';
  else continue; // below position 30 impressions are incidental

  const topQueries = p.queries
    .sort((a, b) => b.impressions - a.impressions)
    .slice(0, 3)
    .map(q => `${q.query} (${q.impressions} impr., pos. ${q.position.toFixed(1)})`);

  out.push({ json: {
    page: p.page,
    impressions: p.impressions,
    clicks: p.clicks,
    ctr: Number(ctr.toFixed(2)),
    position: Number(position.toFixed(1)),
    reason,
    topQueries,
    // estimate: clicks a typical CTR for this position would bring
    potentialClicks: Math.round(p.impressions * (position <= 3 ? 0.15 : position <= 10 ? 0.05 : 0.01))
  }});
}

return out.sort((a, b) => b.json.impressions - a.json.impressions).slice(0, 25);

parameters.message:
={{ $json.data.map(r => `${r.reason} | ${r.page}
  ${r.impressions} impressions, ${r.clicks} clicks, CTR ${r.ctr}%, position ${r.position}
  potential: ~${r.potentialClicks} clicks/month
  queries: ${r.topQueries.join('; ')}`).join('

') }}
